{
  "case_id": "C05",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "The access problem",
      "narration": "Talking therapy is the recommended first-line treatment for long-term insomnia. The catch is that there aren't enough therapists to go round. So can an app do the job instead?",
      "on_screen": "Person awake at night; caption: 'CBT for insomnia — first-line, but hard to access'",
      "claim_refs": ["SYN-C05/background", "SYN-C05/discussion"]
    },
    {
      "beat": "How it was tested",
      "narration": "Six hundred and forty adults with chronic insomnia were randomly split between a six-week CBT app and a basic sleep-hygiene app. Crucially, the researchers registered two success measures in advance: night-time insomnia symptoms, and how people function in daily life.",
      "on_screen": "640 adults split 1:1 into two arms; two pre-registered endpoints listed side by side",
      "claim_refs": ["SYN-C05/abstract", "SYN-C05/methods", "SYN-C05/design"]
    },
    {
      "beat": "Result one: symptoms improved",
      "narration": "On the insomnia symptom scale at week eight, the CBT group improved by 6.8 points, against 3.1 in the control group. That's a 3.7-point advantage, and the result is unlikely to be chance.",
      "on_screen": "Bar chart: −6.8 vs −3.1; callout 'difference 3.7 points, 95% CI 2.9 to 4.5, p<0.001'",
      "claim_refs": ["SYN-C05/results/ISI_week8"]
    },
    {
      "beat": "Result two: daytime function didn't",
      "narration": "But on the second measure, how well people managed work and social life, the two apps were indistinguishable. Just 0.2 points apart, and the range of plausible values includes no benefit at all.",
      "on_screen": "Bar chart: −1.2 vs −1.0; callout 'difference 0.2 points, 95% CI −0.7 to 1.1, p=0.66'",
      "claim_refs": ["SYN-C05/results/WSAS_week8"]
    },
    {
      "beat": "Fading, and the caveats",
      "narration": "The sleep benefit also faded: by six months the gap had narrowed to 1.9 points. And everything here was self-reported, with no sleep-lab measurements. So the honest summary is this: the app eased insomnia symptoms, but it has yet to show that it changes people's days.",
      "on_screen": "Line dropping from 3.7 to 1.9 points at 6 months; caption 'self-reported outcomes only'; final card 'Symptoms: yes. Daytime function: not shown.'",
      "claim_refs": ["SYN-C05/results/ISI_6mo", "SYN-C05/limitations", "SYN-C05/conclusion"]
    }
  ]
}
